import { Component } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { AuthService } from './services/auth.service';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  // We hide the sidebar on the login page, since a logged-out
  // visitor shouldn't see navigation to protected pages.
  showShell = false;

  constructor(public auth: AuthService, private router: Router) {
    this.router.events.subscribe(event => {
      if (event instanceof NavigationEnd) {
        this.showShell = event.urlAfterRedirects !== '/login';
      }
    });
  }

  get currentUserName(): string {
    return this.auth.getUser()?.fullName || 'User';
  }

  logout(): void {
    this.auth.logout();
    this.router.navigate(['/login']);
  }
}
<div class="shell" *ngIf="showShell; else bare">
  <aside class="sidebar">
    <div class="brand-mark">MS</div>
    <nav>
      <a routerLink="/dashboard" routerLinkActive="active">
        <span>Dashboard</span>
      </a>
      <a routerLink="/bookings" routerLinkActive="active">
        <span>Bookings</span>
      </a>
      <a routerLink="/invoices" routerLinkActive="active">
        <span>Invoices</span>
      </a>
    </nav>
  </aside>

  <div class="main">
    <header class="topbar">
      <div>
        <h2>MediaLedger</h2>
        <p class="sub">Media Invoice Tracker</p>
      </div>
      <div class="user-area">
        <span>{{ currentUserName }}</span>
        <button class="btn btn-outline" (click)="logout()">Log out</button>
      </div>
    </header>

    <main class="content">
      <router-outlet></router-outlet>
    </main>
  </div>
</div>

<ng-template #bare>
  <router-outlet></router-outlet>
</ng-template>
